00048 // ********************************** DCT-II **********************************
00049 
00050 //Fast DCT-II transforms
00051 void fastForwardDCT2_B2(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
00052 {
00053   int j;
00054   TCoeff E, O;
00055   TCoeff add = (shift > 0) ? (1 << (shift - 1)) : 0;
00056 
00057   const TMatrixCoeff *iT = g_trCoreDCT2P2[TRANSFORM_FORWARD][0];
00058 
00059   TCoeff *pCoef = dst;
00060   const int  reducedLine = line - iSkipLine;
00061   for (j = 0; j<reducedLine; j++)
00062   {
00063     /* E and O */
00064     E = src[0] + src[1];
00065     O = src[0] - src[1];
00066 
00067     dst[0] = (iT[0] * E + add) >> shift;
00068     dst[line] = (iT[2] * O + add) >> shift;
00069 
00070 
00071     src += 2;
00072     dst++;
00073   }
00074   if (iSkipLine)
00075   {
00076     dst = pCoef + reducedLine;
00077     for (j = 0; j<2; j++)
00078     {
00079       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
00080       dst += line;
00081     }
00082   }
00083 }
00084 
00085 void fastInverseDCT2_B2(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
00086 {
00087   int j;
00088   TCoeff E, O;
00089   TCoeff add = TCoeff(1) << (shift - 1);
00090 
00091   const TMatrixCoeff *iT = g_trCoreDCT2P2[TRANSFORM_INVERSE][0];
00092 
00093   const int  reducedLine = line - iSkipLine;
00094   for (j = 0; j<reducedLine; j++)
00095   {
00096     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00097     E = iT[0] * (src[0] + src[line]);
00098     O = iT[2] * (src[0] - src[line]);
00099 
00100     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00101     dst[0] = Clip3<TCoeff>(outputMinimum, outputMaximum, (E + add) >> shift);
00102     dst[1] = Clip3<TCoeff>(outputMinimum, outputMaximum, (O + add) >> shift);
00103 
00104     src++;
00105     dst += 2;
00106   }
00107   if (iSkipLine)
00108   {
00109     memset(dst, 0, (iSkipLine << 1) * sizeof(TCoeff));
00110   }
00111 }
00112 
00119 void fastForwardDCT2_B4(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
00120 {
00121   int j;
00122   TCoeff E[2], O[2];
00123   TCoeff add = (shift > 0) ? (1 << (shift - 1)) : 0;
00124 
00125   const TMatrixCoeff *iT = g_trCoreDCT2P4[TRANSFORM_FORWARD][0];
00126 
00127   TCoeff *pCoef = dst;
00128   const int  reducedLine = line - iSkipLine;
00129   for (j = 0; j<reducedLine; j++)
00130   {
00131     /* E and O */
00132     E[0] = src[0] + src[3];
00133     O[0] = src[0] - src[3];
00134     E[1] = src[1] + src[2];
00135     O[1] = src[1] - src[2];
00136 
00137     dst[0] = (iT[0] * E[0] + iT[1] * E[1] + add) >> shift;
00138     dst[2 * line] = (iT[8] * E[0] + iT[9] * E[1] + add) >> shift;
00139     dst[line] = (iT[4] * O[0] + iT[5] * O[1] + add) >> shift;
00140     dst[3 * line] = (iT[12] * O[0] + iT[13] * O[1] + add) >> shift;
00141 
00142     src += 4;
00143     dst++;
00144   }
00145   if (iSkipLine)
00146   {
00147     dst = pCoef + reducedLine;
00148     for (j = 0; j<4; j++)
00149     {
00150       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
00151       dst += line;
00152     }
00153   }
00154 }
00155 
00164 void fastInverseDCT2_B4( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum )
00165 {
00166   int j;
00167   TCoeff E[2], O[2];
00168   TCoeff add = TCoeff(1) << ( shift - 1 );
00169 
00170   const TMatrixCoeff *iT = g_trCoreDCT2P4[TRANSFORM_INVERSE][0];
00171 
00172   const int  reducedLine = line - iSkipLine;
00173   for( j = 0; j < reducedLine; j++ )
00174   {
00175     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00176     O[0] = iT[1 * 4 + 0] * src[line] + iT[3 * 4 + 0] * src[3 * line];
00177     O[1] = iT[1 * 4 + 1] * src[line] + iT[3 * 4 + 1] * src[3 * line];
00178     E[0] = iT[0 * 4 + 0] * src[   0] + iT[2 * 4 + 0] * src[2 * line];
00179     E[1] = iT[0 * 4 + 1] * src[   0] + iT[2 * 4 + 1] * src[2 * line];
00180 
00181     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00182     dst[0] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[0] + O[0] + add ) >> shift );
00183     dst[1] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[1] + O[1] + add ) >> shift );
00184     dst[2] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[1] - O[1] + add ) >> shift );
00185     dst[3] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[0] - O[0] + add ) >> shift );
00186 
00187     src++;
00188     dst += 4;
00189   }
00190   if( iSkipLine )
00191   {
00192     memset( dst, 0, ( iSkipLine << 2 ) * sizeof( TCoeff ) );
00193   }
00194 }
