00197 template< int uiTrSize >
00198 inline void _fastInverseMM( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum, const TMatrixCoeff* iT )
00199 {
00200   const TCoeff rnd_factor = TCoeff(1) << (shift - 1);
00201   const int  reducedLine = line - iSkipLine;
00202   const int  cutoff      = uiTrSize - iSkipLine2;
00203 
00204   for( int i = 0; i<reducedLine; i++ )
00205   {
00206     for( int j = 0; j<uiTrSize; j++ )
00207     {
00208       TCoeff iSum = 0;
00209       for( int k = 0; k<cutoff; k++)
00210       {
00211         iSum += src[k*line + i] * iT[k*uiTrSize + j];
00212       }
00213       dst[i*uiTrSize + j] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iSum + rnd_factor) >> shift);
00214     }
00215   }
00216 
00217   if (iSkipLine)
00218   {
00219     memset(dst + (reducedLine*uiTrSize), 0, (iSkipLine*uiTrSize) * sizeof(TCoeff));
00220   }
00221 }
00222 
00223 
00224 template< int uiTrSize >
00225 inline void _fastForwardMM( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TMatrixCoeff* tc )
00226 {
00227   const TCoeff rnd_factor = TCoeff(1) << (shift - 1);
00228   const int  reducedLine = line - iSkipLine;
00229   const int  cutoff      = uiTrSize - iSkipLine2;
00230   TCoeff *pCoef;
00231 
00232   for( int i = 0; i<reducedLine; i++ )
00233   {
00234     pCoef = dst;
00235     const TMatrixCoeff* iT = tc;
00236     for( int j = 0; j<cutoff; j++ )
00237     {
00238       TCoeff iSum = 0;
00239       for( int k = 0; k<uiTrSize; k++ )
00240       {
00241         iSum += src[k] * iT[k];
00242       }
00243       pCoef[i] = (iSum + rnd_factor) >> shift;
00244       pCoef += line;
00245       iT += uiTrSize;
00246     }
00247     src += uiTrSize;
00248   }
00249 
00250   if( iSkipLine )
00251   {
00252     pCoef = dst + reducedLine;
00253     for( int j = 0; j<cutoff; j++ )
00254     {
00255       memset(pCoef, 0, sizeof(TCoeff) * iSkipLine);
00256       pCoef += line;
00257     }
00258   }
00259 
00260   if( iSkipLine2 )
00261   {
00262     pCoef = dst + line*cutoff;
00263     memset(pCoef, 0, sizeof(TCoeff) * line * iSkipLine2);
00264   }
00265 }
