00275 void fastForwardDCT2_B8( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2 )
00276 {
00277   int j, k;
00278   TCoeff E[4], O[4];
00279   TCoeff EE[2], EO[2];
00280   TCoeff add = ( shift > 0 ) ? ( 1 << ( shift - 1 ) ) : 0;
00281 
00282   const TMatrixCoeff *iT = g_trCoreDCT2P8[TRANSFORM_FORWARD][0];
00283 
00284   TCoeff *pCoef = dst;
00285   const int  reducedLine = line - iSkipLine;
00286   for( j = 0; j < reducedLine; j++ )
00287   {
00288     /* E and O*/
00289     for( k = 0; k < 4; k++ )
00290     {
00291       E[k] = src[k] + src[7 - k];
00292       O[k] = src[k] - src[7 - k];
00293     }
00294     /* EE and EO */
00295     EE[0] = E[0] + E[3];
00296     EO[0] = E[0] - E[3];
00297     EE[1] = E[1] + E[2];
00298     EO[1] = E[1] - E[2];
00299 
00300     dst[0       ] = (iT[ 0] * EE[0] + iT[ 1] * EE[1] + add) >> shift;
00301     dst[4 * line] = (iT[32] * EE[0] + iT[33] * EE[1] + add) >> shift;
00302     dst[2 * line] = (iT[16] * EO[0] + iT[17] * EO[1] + add) >> shift;
00303     dst[6 * line] = (iT[48] * EO[0] + iT[49] * EO[1] + add) >> shift;
00304 
00305     dst[    line] = (iT[ 8] * O[0] + iT[ 9] * O[1] + iT[10] * O[2] + iT[11] * O[3] + add) >> shift;
00306     dst[3 * line] = (iT[24] * O[0] + iT[25] * O[1] + iT[26] * O[2] + iT[27] * O[3] + add) >> shift;
00307     dst[5 * line] = (iT[40] * O[0] + iT[41] * O[1] + iT[42] * O[2] + iT[43] * O[3] + add) >> shift;
00308     dst[7 * line] = (iT[56] * O[0] + iT[57] * O[1] + iT[58] * O[2] + iT[59] * O[3] + add) >> shift;
00309 
00310     src += 8;
00311     dst++;
00312   }
00313   if( iSkipLine )
00314   {
00315     dst = pCoef + reducedLine;
00316     for( j = 0; j < 8; j++ )
00317     {
00318       memset( dst, 0, sizeof( TCoeff )*iSkipLine );
00319       dst += line;
00320     }
00321   }
00322 }
00323 
00332 void fastInverseDCT2_B8(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
00333 {
00334   int j, k;
00335   TCoeff E[4], O[4];
00336   TCoeff EE[2], EO[2];
00337   TCoeff add = TCoeff(1) << (shift - 1);
00338 
00339   const TMatrixCoeff *iT = g_trCoreDCT2P8[TRANSFORM_INVERSE][0];
00340 
00341   const int  reducedLine = line - iSkipLine;
00342   for( j = 0; j < reducedLine; j++ )
00343   {
00344     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00345     for( k = 0; k < 4; k++ )
00346     {
00347       O[k] = iT[1 * 8 + k] * src[line] + iT[3 * 8 + k] * src[3 * line] + iT[5 * 8 + k] * src[5 * line] + iT[7 * 8 + k] * src[7 * line];
00348     }
00349 
00350     EO[0] = iT[2 * 8 + 0] * src[2 * line] + iT[6 * 8 + 0] * src[6 * line];
00351     EO[1] = iT[2 * 8 + 1] * src[2 * line] + iT[6 * 8 + 1] * src[6 * line];
00352     EE[0] = iT[0 * 8 + 0] * src[0       ] + iT[4 * 8 + 0] * src[4 * line];
00353     EE[1] = iT[0 * 8 + 1] * src[0       ] + iT[4 * 8 + 1] * src[4 * line];
00354 
00355     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00356     E[0] = EE[0] + EO[0];
00357     E[3] = EE[0] - EO[0];
00358     E[1] = EE[1] + EO[1];
00359     E[2] = EE[1] - EO[1];
00360 
00361     for( k = 0; k < 4; k++ )
00362     {
00363       dst[k    ] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[    k] + O[    k] + add ) >> shift );
00364       dst[k + 4] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[3 - k] - O[3 - k] + add ) >> shift );
00365     }
00366     src++;
00367     dst += 8;
00368   }
00369   if( iSkipLine )
00370   {
00371     memset( dst, 0, ( iSkipLine << 3 ) * sizeof( TCoeff ) );
00372   }
00373 }
00374 
00375 
00382 void fastForwardDCT2_B16(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
00383 {
00384   int j, k;
00385   TCoeff E  [8], O  [8];
00386   TCoeff EE [4], EO [4];
00387   TCoeff EEE[2], EEO[2];
00388   TCoeff add = ( shift > 0 ) ? ( 1 << ( shift - 1 ) ) : 0;
00389 
00390   const TMatrixCoeff *iT = g_trCoreDCT2P16[TRANSFORM_FORWARD][0];
00391 
00392   TCoeff *pCoef = dst;
00393   const int  reducedLine = line - iSkipLine;
00394   for( j = 0; j < reducedLine; j++ )
00395   {
00396     /* E and O*/
00397     for( k = 0; k < 8; k++ )
00398     {
00399       E[k] = src[k] + src[15 - k];
00400       O[k] = src[k] - src[15 - k];
00401     }
00402     /* EE and EO */
00403     for( k = 0; k < 4; k++ )
00404     {
00405       EE[k] = E[k] + E[7 - k];
00406       EO[k] = E[k] - E[7 - k];
00407     }
00408     /* EEE and EEO */
00409     EEE[0] = EE[0] + EE[3];
00410     EEO[0] = EE[0] - EE[3];
00411     EEE[1] = EE[1] + EE[2];
00412     EEO[1] = EE[1] - EE[2];
00413 
00414     dst[ 0       ] = ( iT[ 0     ] * EEE[0] + iT[          1] * EEE[1] + add ) >> shift;
00415     dst[ 8 * line] = ( iT[ 8 * 16] * EEE[0] + iT[ 8 * 16 + 1] * EEE[1] + add ) >> shift;
00416     dst[ 4 * line] = ( iT[ 4 * 16] * EEO[0] + iT[ 4 * 16 + 1] * EEO[1] + add ) >> shift;
00417     dst[12 * line] = ( iT[12 * 16] * EEO[0] + iT[12 * 16 + 1] * EEO[1] + add ) >> shift;
00418 
00419     for( k = 2; k < 16; k += 4 )
00420     {
00421       dst[k*line] = ( iT[k * 16] * EO[0] + iT[k * 16 + 1] * EO[1] + iT[k * 16 + 2] * EO[2] + iT[k * 16 + 3] * EO[3] + add ) >> shift;
00422     }
00423 
00424     for( k = 1; k < 16; k += 2 )
00425     {
00426       dst[k*line] = ( iT[k * 16    ] * O[0] + iT[k * 16 + 1] * O[1] + iT[k * 16 + 2] * O[2] + iT[k * 16 + 3] * O[3] +
00427                       iT[k * 16 + 4] * O[4] + iT[k * 16 + 5] * O[5] + iT[k * 16 + 6] * O[6] + iT[k * 16 + 7] * O[7] + add ) >> shift;
00428     }
00429 
00430     src += 16;
00431     dst++;
00432 
00433   }
00434   if( iSkipLine )
00435   {
00436     dst = pCoef + reducedLine;
00437     for( j = 0; j < 16; j++ )
00438     {
00439       memset( dst, 0, sizeof( TCoeff )*iSkipLine );
00440       dst += line;
00441     }
00442   }
00443 }
00444 
00453 void fastInverseDCT2_B16( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum )
00454 {
00455   int j, k;
00456   TCoeff E  [8], O  [8];
00457   TCoeff EE [4], EO [4];
00458   TCoeff EEE[2], EEO[2];
00459   TCoeff add = TCoeff(1) << ( shift - 1 );
00460 
00461   const TMatrixCoeff *iT = g_trCoreDCT2P16[TRANSFORM_INVERSE][0];
00462 
00463   const int  reducedLine = line - iSkipLine;
00464 
00465   for( j = 0; j < reducedLine; j++ )
00466   {
00467     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00468     for( k = 0; k < 8; k++ )
00469     {
00470       O[k] = iT[1 * 16 + k] * src[    line] + iT[ 3 * 16 + k] * src[ 3 * line] + iT[ 5 * 16 + k] * src[ 5 * line] + iT[ 7 * 16 + k] * src[ 7 * line] +
00471         iT[9 * 16 + k] * src[9 * line] + iT[11 * 16 + k] * src[11 * line] + iT[13 * 16 + k] * src[13 * line] + iT[15 * 16 + k] * src[15 * line];
00472     }
00473     for( k = 0; k < 4; k++ )
00474     {
00475       EO[k] = iT[2 * 16 + k] * src[2 * line] + iT[6 * 16 + k] * src[6 * line] + iT[10 * 16 + k] * src[10 * line] + iT[14 * 16 + k] * src[14 * line];
00476     }
00477     EEO[0] = iT[4 * 16    ] * src[4 * line] + iT[12 * 16    ] * src[12 * line];
00478     EEE[0] = iT[0         ] * src[0       ] + iT[ 8 * 16    ] * src[ 8 * line];
00479     EEO[1] = iT[4 * 16 + 1] * src[4 * line] + iT[12 * 16 + 1] * src[12 * line];
00480     EEE[1] = iT[0 * 16 + 1] * src[0       ] + iT[ 8 * 16 + 1] * src[ 8 * line];
00481 
00482     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00483     for( k = 0; k < 2; k++ )
00484     {
00485       EE[k    ] = EEE[    k] + EEO[    k];
00486       EE[k + 2] = EEE[1 - k] - EEO[1 - k];
00487     }
00488     for( k = 0; k < 4; k++ )
00489     {
00490       E[k    ] = EE[    k] + EO[    k];
00491       E[k + 4] = EE[3 - k] - EO[3 - k];
00492     }
00493     for( k = 0; k < 8; k++ )
00494     {
00495       dst[k    ] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[    k] + O[    k] + add ) >> shift );
00496       dst[k + 8] = Clip3<TCoeff>( outputMinimum, outputMaximum, ( E[7 - k] - O[7 - k] + add ) >> shift );
00497     }
00498     src++;
00499     dst += 16;
00500   }
00501   if( iSkipLine )
00502   {
00503     memset( dst, 0, ( iSkipLine << 4 ) * sizeof( TCoeff ) );
00504   }
00505 }
00506 
00513 void fastForwardDCT2_B32( const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2 )
00514 {
00515   int j, k;
00516   TCoeff E   [16], O   [16];
00517   TCoeff EE  [ 8], EO  [ 8];
00518   TCoeff EEE [ 4], EEO [ 4];
00519   TCoeff EEEE[ 2], EEEO[ 2];
00520   TCoeff add = ( shift > 0 ) ? ( 1 << ( shift - 1 ) ) : 0;
00521 
00522   const TMatrixCoeff *iT = g_trCoreDCT2P32[TRANSFORM_FORWARD][0];
00523 
00524   TCoeff *pCoef = dst;
00525   const int  reducedLine = line - iSkipLine;
00526   for (j = 0; j<reducedLine; j++)
00527   {
00528     /* E and O*/
00529     for (k = 0;k<16;k++)
00530     {
00531       E[k] = src[k] + src[31 - k];
00532       O[k] = src[k] - src[31 - k];
00533     }
00534     /* EE and EO */
00535     for (k = 0;k<8;k++)
00536     {
00537       EE[k] = E[k] + E[15 - k];
00538       EO[k] = E[k] - E[15 - k];
00539     }
00540     /* EEE and EEO */
00541     for (k = 0;k<4;k++)
00542     {
00543       EEE[k] = EE[k] + EE[7 - k];
00544       EEO[k] = EE[k] - EE[7 - k];
00545     }
00546     /* EEEE and EEEO */
00547     EEEE[0] = EEE[0] + EEE[3];
00548     EEEO[0] = EEE[0] - EEE[3];
00549     EEEE[1] = EEE[1] + EEE[2];
00550     EEEO[1] = EEE[1] - EEE[2];
00551 
00552     dst[0] = (iT[0 * 32 + 0] * EEEE[0] + iT[0 * 32 + 1] * EEEE[1] + add) >> shift;
00553     dst[16 * line] = (iT[16 * 32 + 0] * EEEE[0] + iT[16 * 32 + 1] * EEEE[1] + add) >> shift;
00554     dst[8 * line] = (iT[8 * 32 + 0] * EEEO[0] + iT[8 * 32 + 1] * EEEO[1] + add) >> shift;
00555     dst[24 * line] = (iT[24 * 32 + 0] * EEEO[0] + iT[24 * 32 + 1] * EEEO[1] + add) >> shift;
00556     for (k = 4;k<32;k += 8)
00557     {
00558       dst[k*line] = (iT[k * 32 + 0] * EEO[0] + iT[k * 32 + 1] * EEO[1] + iT[k * 32 + 2] * EEO[2] + iT[k * 32 + 3] * EEO[3] + add) >> shift;
00559     }
00560     for (k = 2;k<32;k += 4)
00561     {
00562       dst[k*line] = (iT[k * 32 + 0] * EO[0] + iT[k * 32 + 1] * EO[1] + iT[k * 32 + 2] * EO[2] + iT[k * 32 + 3] * EO[3] +
00563                       iT[k * 32 + 4] * EO[4] + iT[k * 32 + 5] * EO[5] + iT[k * 32 + 6] * EO[6] + iT[k * 32 + 7] * EO[7] + add) >> shift;
00564     }
00565     for (k = 1;k<32;k += 2)
00566     {
00567       dst[k*line] = (iT[k * 32 + 0] * O[0] + iT[k * 32 + 1] * O[1] + iT[k * 32 + 2] * O[2] + iT[k * 32 + 3] * O[3] +
00568                       iT[k * 32 + 4] * O[4] + iT[k * 32 + 5] * O[5] + iT[k * 32 + 6] * O[6] + iT[k * 32 + 7] * O[7] +
00569                       iT[k * 32 + 8] * O[8] + iT[k * 32 + 9] * O[9] + iT[k * 32 + 10] * O[10] + iT[k * 32 + 11] * O[11] +
00570                       iT[k * 32 + 12] * O[12] + iT[k * 32 + 13] * O[13] + iT[k * 32 + 14] * O[14] + iT[k * 32 + 15] * O[15] + add) >> shift;
00571     }
00572     src += 32;
00573     dst++;
00574   }
00575   if (iSkipLine)
00576   {
00577     dst = pCoef + reducedLine;
00578     for (j = 0; j<32; j++)
00579     {
00580       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
00581       dst += line;
00582     }
00583   }
00584 }
