00594 void fastInverseDCT2_B32(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
00595 {
00596   TCoeff j, k;
00597   TCoeff E[16], O[16];
00598   TCoeff EE[8], EO[8];
00599   TCoeff EEE[4], EEO[4];
00600   TCoeff EEEE[2], EEEO[2];
00601   TCoeff add = TCoeff(1) << (shift - 1);
00602 
00603   const TMatrixCoeff *iT = g_trCoreDCT2P32[TRANSFORM_INVERSE][0];
00604 
00605   const int  reducedLine = line - iSkipLine;
00606   for (j = 0; j<reducedLine; j++)
00607   {
00608     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00609     for (k = 0;k<16;k++)
00610     {
00611       O[k] = iT[1 * 32 + k] * src[line] + iT[3 * 32 + k] * src[3 * line] + iT[5 * 32 + k] * src[5 * line] + iT[7 * 32 + k] * src[7 * line] +
00612         iT[9 * 32 + k] * src[9 * line] + iT[11 * 32 + k] * src[11 * line] + iT[13 * 32 + k] * src[13 * line] + iT[15 * 32 + k] * src[15 * line] +
00613         iT[17 * 32 + k] * src[17 * line] + iT[19 * 32 + k] * src[19 * line] + iT[21 * 32 + k] * src[21 * line] + iT[23 * 32 + k] * src[23 * line] +
00614         iT[25 * 32 + k] * src[25 * line] + iT[27 * 32 + k] * src[27 * line] + iT[29 * 32 + k] * src[29 * line] + iT[31 * 32 + k] * src[31 * line];
00615     }
00616     for (k = 0;k<8;k++)
00617     {
00618       EO[k] = iT[2 * 32 + k] * src[2 * line] + iT[6 * 32 + k] * src[6 * line] + iT[10 * 32 + k] * src[10 * line] + iT[14 * 32 + k] * src[14 * line] +
00619         iT[18 * 32 + k] * src[18 * line] + iT[22 * 32 + k] * src[22 * line] + iT[26 * 32 + k] * src[26 * line] + iT[30 * 32 + k] * src[30 * line];
00620     }
00621     for (k = 0;k<4;k++)
00622     {
00623       EEO[k] = iT[4 * 32 + k] * src[4 * line] + iT[12 * 32 + k] * src[12 * line] + iT[20 * 32 + k] * src[20 * line] + iT[28 * 32 + k] * src[28 * line];
00624     }
00625     EEEO[0] = iT[8 * 32 + 0] * src[8 * line] + iT[24 * 32 + 0] * src[24 * line];
00626     EEEO[1] = iT[8 * 32 + 1] * src[8 * line] + iT[24 * 32 + 1] * src[24 * line];
00627     EEEE[0] = iT[0 * 32 + 0] * src[0] + iT[16 * 32 + 0] * src[16 * line];
00628     EEEE[1] = iT[0 * 32 + 1] * src[0] + iT[16 * 32 + 1] * src[16 * line];
00629 
00630     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00631     EEE[0] = EEEE[0] + EEEO[0];
00632     EEE[3] = EEEE[0] - EEEO[0];
00633     EEE[1] = EEEE[1] + EEEO[1];
00634     EEE[2] = EEEE[1] - EEEO[1];
00635     for (k = 0;k<4;k++)
00636     {
00637       EE[k] = EEE[k] + EEO[k];
00638       EE[k + 4] = EEE[3 - k] - EEO[3 - k];
00639     }
00640     for (k = 0;k<8;k++)
00641     {
00642       E[k] = EE[k] + EO[k];
00643       E[k + 8] = EE[7 - k] - EO[7 - k];
00644     }
00645     for (k = 0;k<16;k++)
00646     {
00647       dst[k] = Clip3<TCoeff>(outputMinimum, outputMaximum, (E[k] + O[k] + add) >> shift);
00648       dst[k + 16] = Clip3<TCoeff>(outputMinimum, outputMaximum, (E[15 - k] - O[15 - k] + add) >> shift);
00649     }
00650     src++;
00651     dst += 32;
00652   }
00653   if (iSkipLine)
00654   {
00655     memset(dst, 0, (iSkipLine << 5) * sizeof(TCoeff));
00656   }
00657 }
