00659 void fastForwardDCT2_B64(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
00660 {
00661   int rnd_factor = 1 << (shift - 1);
00662 
00663   const int uiTrSize = 64;
00664   const TMatrixCoeff *iT = g_trCoreDCT2P64[TRANSFORM_FORWARD][0];
00665 
00666   int   j, k;
00667   TCoeff E[32], O[32];
00668   TCoeff EE[16], EO[16];
00669   TCoeff EEE[8], EEO[8];
00670   TCoeff EEEE[4], EEEO[4];
00671   TCoeff EEEEE[2], EEEEO[2];
00672   TCoeff *tmp = dst;
00673 
00674   //bool zo = iSkipLine2 >= 32;
00675   bool zo = iSkipLine2 != 0;
00676   for (j = 0; j<line - iSkipLine; j++)
00677   {
00678     /* E and O*/
00679     for (k = 0;k<32;k++)
00680     {
00681       E[k] = src[k] + src[63 - k];
00682       O[k] = src[k] - src[63 - k];
00683     }
00684     /* EE and EO */
00685     for (k = 0;k<16;k++)
00686     {
00687       EE[k] = E[k] + E[31 - k];
00688       EO[k] = E[k] - E[31 - k];
00689     }
00690     /* EEE and EEO */
00691     for (k = 0;k<8;k++)
00692     {
00693       EEE[k] = EE[k] + EE[15 - k];
00694       EEO[k] = EE[k] - EE[15 - k];
00695     }
00696     /* EEEE and EEEO */
00697     for (k = 0;k<4;k++)
00698     {
00699       EEEE[k] = EEE[k] + EEE[7 - k];
00700       EEEO[k] = EEE[k] - EEE[7 - k];
00701     }
00702     /* EEEEE and EEEEO */
00703     EEEEE[0] = EEEE[0] + EEEE[3];
00704     EEEEO[0] = EEEE[0] - EEEE[3];
00705     EEEEE[1] = EEEE[1] + EEEE[2];
00706     EEEEO[1] = EEEE[1] - EEEE[2];
00707 
00708     dst[0] = (iT[0 * 64 + 0] * EEEEE[0] + iT[0 * 64 + 1] * EEEEE[1] + rnd_factor) >> shift;
00709     dst[16 * line] = (iT[16 * 64 + 0] * EEEEO[0] + iT[16 * 64 + 1] * EEEEO[1] + rnd_factor) >> shift;
00710 
00711     if (!zo)
00712     {
00713       dst[32 * line] = (iT[32 * 64 + 0] * EEEEE[0] + iT[32 * 64 + 1] * EEEEE[1] + rnd_factor) >> shift;
00714       dst[48 * line] = (iT[48 * 64 + 0] * EEEEO[0] + iT[48 * 64 + 1] * EEEEO[1] + rnd_factor) >> shift;
00715     }
00716     for (k = 8;k<(zo ? 32 : 64);k += 16)
00717     {
00718       dst[k*line] = (iT[k * 64 + 0] * EEEO[0] + iT[k * 64 + 1] * EEEO[1] + iT[k * 64 + 2] * EEEO[2] + iT[k * 64 + 3] * EEEO[3] + rnd_factor) >> shift;
00719     }
00720     for (k = 4;k<(zo ? 32 : 64);k += 8)
00721     {
00722       dst[k*line] = (iT[k * 64 + 0] * EEO[0] + iT[k * 64 + 1] * EEO[1] + iT[k * 64 + 2] * EEO[2] + iT[k * 64 + 3] * EEO[3] +
00723                       iT[k * 64 + 4] * EEO[4] + iT[k * 64 + 5] * EEO[5] + iT[k * 64 + 6] * EEO[6] + iT[k * 64 + 7] * EEO[7] + rnd_factor) >> shift;
00724     }
00725     for (k = 2;k<(zo ? 32 : 64);k += 4)
00726     {
00727       dst[k*line] = (iT[k * 64 + 0] * EO[0] + iT[k * 64 + 1] * EO[1] + iT[k * 64 + 2] * EO[2] + iT[k * 64 + 3] * EO[3] +
00728                       iT[k * 64 + 4] * EO[4] + iT[k * 64 + 5] * EO[5] + iT[k * 64 + 6] * EO[6] + iT[k * 64 + 7] * EO[7] +
00729                       iT[k * 64 + 8] * EO[8] + iT[k * 64 + 9] * EO[9] + iT[k * 64 + 10] * EO[10] + iT[k * 64 + 11] * EO[11] +
00730                       iT[k * 64 + 12] * EO[12] + iT[k * 64 + 13] * EO[13] + iT[k * 64 + 14] * EO[14] + iT[k * 64 + 15] * EO[15] + rnd_factor) >> shift;
00731     }
00732     for (k = 1;k<(zo ? 32 : 64);k += 2)
00733     {
00734       dst[k*line] = (iT[k * 64 + 0] * O[0] + iT[k * 64 + 1] * O[1] + iT[k * 64 + 2] * O[2] + iT[k * 64 + 3] * O[3] +
00735                       iT[k * 64 + 4] * O[4] + iT[k * 64 + 5] * O[5] + iT[k * 64 + 6] * O[6] + iT[k * 64 + 7] * O[7] +
00736                       iT[k * 64 + 8] * O[8] + iT[k * 64 + 9] * O[9] + iT[k * 64 + 10] * O[10] + iT[k * 64 + 11] * O[11] +
00737                       iT[k * 64 + 12] * O[12] + iT[k * 64 + 13] * O[13] + iT[k * 64 + 14] * O[14] + iT[k * 64 + 15] * O[15] +
00738                       iT[k * 64 + 16] * O[16] + iT[k * 64 + 17] * O[17] + iT[k * 64 + 18] * O[18] + iT[k * 64 + 19] * O[19] +
00739                       iT[k * 64 + 20] * O[20] + iT[k * 64 + 21] * O[21] + iT[k * 64 + 22] * O[22] + iT[k * 64 + 23] * O[23] +
00740                       iT[k * 64 + 24] * O[24] + iT[k * 64 + 25] * O[25] + iT[k * 64 + 26] * O[26] + iT[k * 64 + 27] * O[27] +
00741                       iT[k * 64 + 28] * O[28] + iT[k * 64 + 29] * O[29] + iT[k * 64 + 30] * O[30] + iT[k * 64 + 31] * O[31] + rnd_factor) >> shift;
00742     }
00743     src += uiTrSize;
00744     dst++;
00745   }
00746 
00747   const int  reducedLine = line - iSkipLine;
00748   const int  cutoff = uiTrSize - iSkipLine2;
00749   if (iSkipLine)
00750   {
00751     dst = tmp + reducedLine;
00752     for (j = 0; j<cutoff; j++)
00753     {
00754       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
00755       dst += line;
00756     }
00757   }
00758   if (iSkipLine2)
00759   {
00760     dst = tmp + line*cutoff;
00761     memset(dst, 0, sizeof(TCoeff)*line*iSkipLine2);
00762   }
00763 }
