00765 void fastInverseDCT2_B64(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
00766 {
00767   int rnd_factor = 1 << (shift - 1);
00768   const int uiTrSize = 64;
00769   const TMatrixCoeff *iT = g_trCoreDCT2P64[TRANSFORM_INVERSE][0];
00770 
00771   int    j, k;
00772   TCoeff E[32], O[32];
00773   TCoeff EE[16], EO[16];
00774   TCoeff EEE[8], EEO[8];
00775   TCoeff EEEE[4], EEEO[4];
00776   TCoeff EEEEE[2], EEEEO[2];
00777   bool zo = iSkipLine2 >= 32;
00778   for (j = 0; j<line - iSkipLine; j++)
00779   {
00780     /* Utilizing symmetry properties to the maximum to minimize the number of multiplications */
00781     for (k = 0;k<32;k++)
00782     {
00783       O[k] = iT[1 * 64 + k] * src[line] + iT[3 * 64 + k] * src[3 * line] + iT[5 * 64 + k] * src[5 * line] + iT[7 * 64 + k] * src[7 * line] +
00784         iT[9 * 64 + k] * src[9 * line] + iT[11 * 64 + k] * src[11 * line] + iT[13 * 64 + k] * src[13 * line] + iT[15 * 64 + k] * src[15 * line] +
00785         iT[17 * 64 + k] * src[17 * line] + iT[19 * 64 + k] * src[19 * line] + iT[21 * 64 + k] * src[21 * line] + iT[23 * 64 + k] * src[23 * line] +
00786         iT[25 * 64 + k] * src[25 * line] + iT[27 * 64 + k] * src[27 * line] + iT[29 * 64 + k] * src[29 * line] + iT[31 * 64 + k] * src[31 * line] +
00787         (zo ? 0 : (
00788         iT[33 * 64 + k] * src[33 * line] + iT[35 * 64 + k] * src[35 * line] + iT[37 * 64 + k] * src[37 * line] + iT[39 * 64 + k] * src[39 * line] +
00789         iT[41 * 64 + k] * src[41 * line] + iT[43 * 64 + k] * src[43 * line] + iT[45 * 64 + k] * src[45 * line] + iT[47 * 64 + k] * src[47 * line] +
00790         iT[49 * 64 + k] * src[49 * line] + iT[51 * 64 + k] * src[51 * line] + iT[53 * 64 + k] * src[53 * line] + iT[55 * 64 + k] * src[55 * line] +
00791         iT[57 * 64 + k] * src[57 * line] + iT[59 * 64 + k] * src[59 * line] + iT[61 * 64 + k] * src[61 * line] + iT[63 * 64 + k] * src[63 * line]));
00792     }
00793     for (k = 0;k<16;k++)
00794     {
00795       EO[k] = iT[2 * 64 + k] * src[2 * line] + iT[6 * 64 + k] * src[6 * line] + iT[10 * 64 + k] * src[10 * line] + iT[14 * 64 + k] * src[14 * line] +
00796         iT[18 * 64 + k] * src[18 * line] + iT[22 * 64 + k] * src[22 * line] + iT[26 * 64 + k] * src[26 * line] + iT[30 * 64 + k] * src[30 * line] +
00797         (zo ? 0 : (
00798         iT[34 * 64 + k] * src[34 * line] + iT[38 * 64 + k] * src[38 * line] + iT[42 * 64 + k] * src[42 * line] + iT[46 * 64 + k] * src[46 * line] +
00799         iT[50 * 64 + k] * src[50 * line] + iT[54 * 64 + k] * src[54 * line] + iT[58 * 64 + k] * src[58 * line] + iT[62 * 64 + k] * src[62 * line]));
00800     }
00801     for (k = 0;k<8;k++)
00802     {
00803       EEO[k] = iT[4 * 64 + k] * src[4 * line] + iT[12 * 64 + k] * src[12 * line] + iT[20 * 64 + k] * src[20 * line] + iT[28 * 64 + k] * src[28 * line] +
00804         (zo ? 0 : (
00805         iT[36 * 64 + k] * src[36 * line] + iT[44 * 64 + k] * src[44 * line] + iT[52 * 64 + k] * src[52 * line] + iT[60 * 64 + k] * src[60 * line]));
00806     }
00807     for (k = 0;k<4;k++)
00808     {
00809       EEEO[k] = iT[8 * 64 + k] * src[8 * line] + iT[24 * 64 + k] * src[24 * line] + (zo ? 0 : (iT[40 * 64 + k] * src[40 * line] + iT[56 * 64 + k] * src[56 * line]));
00810     }
00811     EEEEO[0] = iT[16 * 64 + 0] * src[16 * line] + (zo ? 0 : iT[48 * 64 + 0] * src[48 * line]);
00812     EEEEO[1] = iT[16 * 64 + 1] * src[16 * line] + (zo ? 0 : iT[48 * 64 + 1] * src[48 * line]);
00813     EEEEE[0] = iT[0 * 64 + 0] * src[0] + (zo ? 0 : iT[32 * 64 + 0] * src[32 * line]);
00814     EEEEE[1] = iT[0 * 64 + 1] * src[0] + (zo ? 0 : iT[32 * 64 + 1] * src[32 * line]);
00815 
00816     /* Combining even and odd terms at each hierarchy levels to calculate the final spatial domain vector */
00817     for (k = 0;k<2;k++)
00818     {
00819       EEEE[k] = EEEEE[k] + EEEEO[k];
00820       EEEE[k + 2] = EEEEE[1 - k] - EEEEO[1 - k];
00821     }
00822     for (k = 0;k<4;k++)
00823     {
00824       EEE[k] = EEEE[k] + EEEO[k];
00825       EEE[k + 4] = EEEE[3 - k] - EEEO[3 - k];
00826     }
00827     for (k = 0;k<8;k++)
00828     {
00829       EE[k] = EEE[k] + EEO[k];
00830       EE[k + 8] = EEE[7 - k] - EEO[7 - k];
00831     }
00832     for (k = 0;k<16;k++)
00833     {
00834       E[k] = EE[k] + EO[k];
00835       E[k + 16] = EE[15 - k] - EO[15 - k];
00836     }
00837     for (k = 0;k<32;k++)
00838     {
00839       dst[k] = Clip3<TCoeff>(outputMinimum, outputMaximum, (E[k] + O[k] + rnd_factor) >> shift);
00840       dst[k + 32] = Clip3<TCoeff>(outputMinimum, outputMaximum, (E[31 - k] - O[31 - k] + rnd_factor) >> shift);
00841     }
00842     src++;
00843     dst += uiTrSize;
00844   }
00845 
00846   memset(dst, 0, uiTrSize*iSkipLine * sizeof(TCoeff));
00847 }
