00852 void fastForwardDST7_B4(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
00853 {
00854   int i;
00855   TCoeff rnd_factor = (shift > 0) ? (1 << (shift - 1)) : 0;
00856 
00857   const TMatrixCoeff *iT = g_trCoreDST7P4[TRANSFORM_FORWARD][0];
00858 
00859   TCoeff c[4];
00860   TCoeff *pCoeff = dst;
00861   const int  reducedLine = line - iSkipLine;
00862   for (i = 0; i<reducedLine; i++)
00863   {
00864     // Intermediate Variables
00865     c[0] = src[0] + src[3];
00866     c[1] = src[1] + src[3];
00867     c[2] = src[0] - src[1];
00868     c[3] = iT[2] * src[2];
00869 
00870     dst[0 * line] = (iT[0] * c[0] + iT[1] * c[1] + c[3] + rnd_factor) >> shift;
00871     dst[1 * line] = (iT[2] * (src[0] + src[1] - src[3]) + rnd_factor) >> shift;
00872     dst[2 * line] = (iT[0] * c[2] + iT[1] * c[0] - c[3] + rnd_factor) >> shift;
00873     dst[3 * line] = (iT[1] * c[2] - iT[0] * c[1] + c[3] + rnd_factor) >> shift;
00874 
00875     src += 4;
00876     dst++;
00877   }
00878   if (iSkipLine)
00879   {
00880     dst = pCoeff + reducedLine;
00881     for (i = 0; i<4; i++)
00882     {
00883       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
00884       dst += line;
00885     }
00886   }
00887 }
