00889 void fastInverseDST7_B4(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
00890 {
00891   int i;
00892   TCoeff c[4];
00893   TCoeff rnd_factor = (shift > 0) ? (1 << (shift - 1)) : 0;
00894 
00895   const TMatrixCoeff *iT = g_trCoreDST7P4[TRANSFORM_INVERSE][0];
00896 
00897   const int  reducedLine = line - iSkipLine;
00898   for (i = 0; i<reducedLine; i++)
00899   {
00900     // Intermediate Variables
00901     c[0] = src[0 * line] + src[2 * line];
00902     c[1] = src[2 * line] + src[3 * line];
00903     c[2] = src[0 * line] - src[3 * line];
00904     c[3] = iT[2] * src[1 * line];
00905 
00906     dst[0] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[0] * c[0] + iT[1] * c[1] + c[3] + rnd_factor) >> shift);
00907     dst[1] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[1] * c[2] - iT[0] * c[1] + c[3] + rnd_factor) >> shift);
