01244 // ********************************** DCT-VIII **********************************
01245 void fastForwardDCT8_B4(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2)
01246 {
01247   int i;
01248   int rnd_factor = 1 << (shift - 1);
01249   const TMatrixCoeff *iT = g_trCoreDCT8P4[TRANSFORM_FORWARD][0];
01250 
01251   TCoeff c[4];
01252   TCoeff *pCoeff = dst;
01253   const int  reducedLine = line - iSkipLine;
01254   for (i = 0; i<reducedLine; i++)
01255   {
01256     // Intermediate Variables
01257     c[0] = src[0] + src[3];
01258     c[1] = src[2] + src[0];
01259     c[2] = src[3] - src[2];
01260     c[3] = iT[1] * src[1];
01261 
01262     dst[0 * line] = (iT[3] * c[0] + iT[2] * c[1] + c[3] + rnd_factor) >> shift;
01263     dst[1 * line] = (iT[1] * (src[0] - src[2] - src[3]) + rnd_factor) >> shift;
01264     dst[2 * line] = (iT[3] * c[2] + iT[2] * c[0] - c[3] + rnd_factor) >> shift;
01265     dst[3 * line] = (iT[3] * c[1] - iT[2] * c[2] - c[3] + rnd_factor) >> shift;
01266 
01267     src += 4;
01268     dst++;
01269   }
01270   if (iSkipLine)
01271   {
01272     dst = pCoeff + reducedLine;
01273     for (i = 0; i<4; i++)
01274     {
01275       memset(dst, 0, sizeof(TCoeff)*iSkipLine);
01276       dst += line;
01277     }
01278   }
01279 }
