01281 void fastInverseDCT8_B4(const TCoeff *src, TCoeff *dst, int shift, int line, int iSkipLine, int iSkipLine2, const TCoeff outputMinimum, const TCoeff outputMaximum)
01282 {
01283   int i;
01284   int rnd_factor = 1 << (shift - 1);
01285 
01286   const TMatrixCoeff *iT = g_trCoreDCT8P4[TRANSFORM_INVERSE][0];
01287 
01288   TCoeff c[4];
01289   const int  reducedLine = line - iSkipLine;
01290   for (i = 0; i<reducedLine; i++)
01291   {
01292     // Intermediate Variables
01293     c[0] = src[0 * line] + src[3 * line];
01294     c[1] = src[2 * line] + src[0 * line];
01295     c[2] = src[3 * line] - src[2 * line];
01296     c[3] = iT[1] * src[1 * line];
01297 
01298     dst[0] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[3] * c[0] + iT[2] * c[1] + c[3] + rnd_factor) >> shift);
01299     dst[1] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[1] * (src[0 * line] - src[2 * line] - src[3 * line]) + rnd_factor) >> shift);
01300     dst[2] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[3] * c[2] + iT[2] * c[0] - c[3] + rnd_factor) >> shift);
01301     dst[3] = Clip3<TCoeff>(outputMinimum, outputMaximum, (iT[3] * c[1] - iT[2] * c[2] - c[3] + rnd_factor) >> shift);
01302     dst += 4;
01303     src++;
01304   }
01305   if (iSkipLine)
01306   {
01307     memset(dst, 0, (iSkipLine << 2) * sizeof(TCoeff));
01308   }
01309 }
