01465     {
01466       a[0][k] = src[31-k] - src[20+k];
01467       a[1][k] = src[31-k] + src[18-k];
01468       a[2][k] = src[31-k] + src[ 7+k];
01469       a[3][k] = src[31-k] - src[ 5-k];
01470       a[4][k] = src[25-k] + src[13+k];
01471       a[5][k] = src[25-k] + src[12-k];
01472       a[6][k] = src[25-k] - src[   k];
01473       a[7][k] = src[18-k] - src[ 7+k];
01474       a[8][k] = src[18-k] + src[ 5-k];
01475       a[9][k] = src[12-k] + src[   k];
